PULL REQUEST TITLE:
modified work_queue_factory to integrate runos into the factory. 

TARGET FILE:
batch_job/src/work_queue_factory.c

RELATED CODE HUNKS IN THE SAME FILE:
<related_hunks>
[{'filename': 'batch_job/src/work_queue_factory.c', 'patch': '@@ -1248,24 +1273,37 @@ int main(int argc, char *argv[])\n \t\treturn 1;\n \t}\n \n-\tchar cmd[1024];\n+\tchar* cmd;\n \tif(worker_command != NULL){\n-\t\tsprintf(cmd,"cp \'%s\' \'%s\'",worker_command,scratch_dir);\n+\t\tcmd = string_format("cp \'%s\' \'%s\'",worker_command,scratch_dir);\n \t\tif(system(cmd)){\n \t\t\tfprintf(stderr, "work_queue_factory: Could not Access specified worker_queue_worker binary.\\n");\n \t\t\texit(EXIT_FAILURE);\n \t\t}\n+\t\tfree(cmd);\n \t}else{\n-\t\tsprintf(cmd,"cp \\"$(which work_queue_worker)\\" \'%s\'",scratch_dir);\n+\t\tcmd = string_format("cp \\"$(which work_queue_worker)\\" \'%s\'",scratch_dir);\n \t\tif (system(cmd)) {\n \t\t\tfprintf(stderr, "work_queue_factory: please add work_queue_worker to your PATH.\\n");\n \t\t\texit(EXIT_FAILURE);\n \t\t}\n+\t\tfree(cmd);\n+\t}\n+\t\n+\t\n+\tif(runos_os) {\n+\t\tcmd = string_format("cp \\"$(which vc3-builder)\\" \'%s\'", scratch_dir);\n+\t\tint k = system(cmd);\n+\t\tif (k) {\n+\t\t\tfprintf(stderr, "can\'t copy vc3-builder! Please make sure it\'s in your path. Error code: %i\\n", k);\n+\t\t\texit(EXIT_FAILURE);\n+\t\t}\n \t}\n \n \tif(password_file) {\n-\t\tsprintf(cmd,"cp %s %s/pwfile",password_file,scratch_dir);\n+\t\tcmd = string_format("cp %s %s/pwfile",password_file,scratch_dir);\n \t\tsystem(cmd);\n+\t\tfree(cmd);\n \t}\n \n \tif(chdir(scratch_dir)!=0) {'}]
</related_hunks>

SURROUNDING CONTEXT:
<context>
char* cmd;
	if(worker_command != NULL){
		cmd = string_format("cp '%s' '%s'",worker_command,scratch_dir);
		if(system(cmd)){
			fprintf(stderr, "work_queue_factory: Could not Access specified worker_queue_worker binary.\n");
			exit(EXIT_FAILURE);
		}
	}else{
		cmd = string_format("cp \"$(which work_queue_worker)\" '%s'",scratch_dir);
		if (system(cmd)) {
			fprintf(stderr, "work_queue_factory: please add work_queue_worker to your PATH.\n");
			exit(EXIT_FAILURE);
		}
	}

	free(cmd);

	if(runos_os) {
		cmd = string_format("cp \"$(which vc3-builder)\" '%s'", scratch_dir);
		int k = system(cmd);
		if (k) {
			fprintf(stderr, "can't copy vc3-builder! Please make sure it's in your path. Error code: %i\n", k);
			exit(EXIT_FAILURE);
		}
	}
</context>

CODE PATCH:
<patch>
@@ -1285,7 +1285,9 @@ int main(int argc, char *argv[])
 			exit(EXIT_FAILURE);
 		}
 	}
-
+	
+	free(cmd);
+	
 	if(runos_os) {
 		cmd = string_format("cp \"$(which vc3-builder)\" '%s'", scratch_dir);
 		int k = system(cmd);

</patch>

REVIEW COMMENT:
The command string allocated for the vc3-builder copy is not freed after system(cmd) completes, causing a leak. Free it on the normal path and before exiting on failure if appropriate.

